def countKItemSubsets(nums, k, target):
    MOD = 10 ** 9 + 7
    ways = [[0] * (target + 1) for _ in range(k + 1)]
    ways[0][0] = 1
    for x in nums:
        if x > target:
            continue
        for j in range(k, 0, -1):
            prev = ways[j - 1]
            row = ways[j]
            for s in range(x, target + 1):
                if prev[s - x]:
                    row[s] = (row[s] + prev[s - x]) % MOD
    return ways[k][target]
